import {stm32Capabilities} from './stm32-capabilities.js';
import {STM32_BOARDS} from './stm32-boards.js';
// This is model coverage, not a claim that every MCU implements each peripheral.
export const STM_SCOPE=[
 ['CPU / exception / FPU','Açık','Gerçek Cortex-M3/M4F komut motoru, NVIC, SysTick, WFI/WFE/SEV ve M4F aritmetiği.','F4 sekiz bölgeli MPU, MemManage ve bit-band eklendi; tüm fault/priority ve çevrim duyarlı pipeline/bus ayrıntıları açık.'],
 ['Flash / SRAM / reset','İlerliyor','Kart belleği; kilit/anahtar, F1 sayfa/F4 sektör erase, program genişliği ve 1→0 kuralı; EOP/hata, 96-bit UID, yoğunluk ve reset kalıcılığı.','Option-byte WRP/RDP/reload, BOOT/NRST ve işlevsel USART boot protokolü eklendi. 64-bit programlama, BSY, PCROP execute-only ve SRAM kaynaklı RDP veri erişimi eklendi. Orijinal ST ROM kodu/USB DFU modeli yok.'],
 ['RCC / saat / güç','Açık','Kart HSE/PLL/APB başlangıcı, çevrebirim enable/reset; RTC kaynakları ve PWR DBP/VOS/ready.','Dinamik HSI/HSE/PLL/AHB/APB, CSS/NMI, PVD/BOR, STOP/STANDBY eklendi. Nominal HSE/PLL ready gecikmeleri ve backup regulator hazır geçişi eklendi. Analog akım/kararlılık ve gerçek toleranslar modellenmiyor.'],
 ['GPIO / EXTI','Uygulama tamam','GPIO/pull/open-drain, gerçek DC hatları; EXTI0..15 mux/edge/mask/PR/SWIER/IRQ/WFE.','GPIO LCKR kilidi ve dahili EXTI hatları eklendi; tam AF/remap ve debug/trace denetimi açık. Slew/damage analog model değil.'],
 ['USART1/2/3/6','Uygulama tamam','DMA; fiziksel 7/8/9-bit, parity,0.5/1/1.5/2stop, hata/IRQ; kart terminali ve F4 OVER8/16.','USART3/6, CTS/RTS ve LIN break eklendi. Half-duplex TX pad, IrDA darbe, synchronous CK, smartcard clock/guard/NACK eklendi. Tam smartcard yeniden deneme ve Nucleo VCP fiziksel köprü ayrıntıları açık.'],
 ['ADC1 / ADC2','Uygulama tamam','ADC1 ve F103 ADC2 regular/injected/discontinuous/watchdog/tetik/IRQ; ADC1 DMA ve dahili TEMP/VREF/VBAT.','Ek timer dış tetikleri eklendi. ADC2 fiziksel DMA üretmez; dual ADC ve analog örnekleme/kalibrasyon ayrıntıları açık.'],
 ['TIM1/2/3/4/5/9/10/11','Uygulama tamam','PWM1/2, output compare, IRQ, one-pulse, capture, encoder, down/center aligned ve prescaler fazı.','Çipte bulunan timer instance’ları, filtre/TRC/remap/external clock ve TIM1 nominal tamamlayıcı/dead-time eklendi. ITR reset/gate/start/external-clock zinciri, TIM1 break/MOE/AOE/idle ve repetition eklendi. Tüm advanced-control kombinasyonları doğrulanmadı.'],
 ['SPI1–5 / I²S','Uygulama tamam','Mode0..3,8/16-bit,MSB/LSB master, alternatif F4 pinleri, NSS/SSOE, fiziksel hat/IRQ/OVR ve DMA.','Çipte bulunan SPI birimleri, slave/NSS/MODF/CRC ve I²S CK/WS/SD eklendi. Receive-only/tek hat/TI ve erişilebilir I²S2/3 MCLK padleri ile right-justified slot eklendi. Tüm stereo format kombinasyonları doğrulanmadı; SAI bu çiplerde yok.'],
 ['I²C1/2/3','Uygulama tamam','100/400 kHz 7-bit master, DMA, repeated-start, EEPROM polling, fiziksel OD/clock wait/IRQ/recovery.','Ek I²C birimleri, 7/10-bit slave, ACK/STOP/IRQ, arbitration kaybı ve SMBus timeout eklendi. PEC gönderim/son-bayt kontrolü eklendi. Tam SMBus ARP/host-notify ve analog rise-time açık.'],
 ['DMA','Uygulama tamam','F1 DMA1/F4 DMA1+2 native ARM bus, normal/circular, width/increment/priority ve HT/TC/TE IRQ.','F4 FIFO width packing, DBM/CT, ek timer/bus ve SDIO PFLOW istekleri eklendi. Burst bus arbitrajı/contestion ve tüm hata zamanlamaları açık.'],
 ['RTC / backup / watchdog','Uygulama tamam','F103/F4 RTC, alarm/wakeup/subsecond/IRQ, backup domain ve IWDG/WWDG gerçek reset nedeni.','Timestamp/tamper/backup erase, kalibrasyon, shift/DST ve PC13 çıktı eklendi. Tamper filtre ve backup regulator nominal hazır geçişi eklendi. Tüm tamper pad/filter kombinasyonları ve analog tolerans/akım doğrulanmadı.'],
 ['CRC','Uygulama tamam','32-bit CRC word register, polinom, IDR/reset ve RCC kapısı; dokuz kartta bağımsız referans kabulü.','Seçili dokuz MCU’da bulunmayan RNG/crypto eksik değildir.'],
 ['USB / CAN / SDIO','Uygulama tamam','F103 PMA + F401/F411 OTG FS device; F103 bxCAN; Nucleo F401/F411 SDIO/SDHC tanıma ve tek/çok blok FIFO. Paketinde tam SDIO pin grubu olmayan WeAct kartlarında doğru biçimde yok gösterilir.','SDIO DMA istekleri eklendi. OTG 8 kanal host, multi-packet/ISO; sanal CAN ağı/arbitration/ACK/bus-off; SDSC/MMC adresleme ve MMC stream eklendi. F401/F411 OTG_FS dahili DMA içermez. Fiziksel transceiver/USB PHY ve tüm paket hata/timing varyantları doğrulanmadı.'],
 ['FMC / QSPI / DCMI / LCD / touch','Çipte yok','Opsiyonel Black Pill SPI flash footprint boş gösterilir.','Bu dokuz MCU içinde FMC/QSPI/DCMI/LTDC denetleyicisi yoktur. Haricî SPI bileşenleri ayrı modellerdir.'],
 ['Dahili analog / sensörler','Uygulama tamam','Haricî sensörler/DC; ADC nominal sıcaklık/VREFINT ve F4 VBAT/4.','Fabrika kalibrasyon/noise değerleri fiziksel MCU ölçümüdür.'],
 ['C17 / C++ / MicroPython','Uygulama tamam','Gerçek ARM C17/C++17; çok dosya/linker/heap/IRQ; MicroPython WASM elektriksel devre modu.','Cube/vendor HAL, tam masaüstü STL ve yerel ARM MicroPython dağıtımı ayrı ürün/toolchain değildir.'],
 ['Kart / şema / doğrulama','Uygulama tamam','Dokuz Blue Pill/Nucleo/WeAct profilinde header/bellek/LED/KEY, devre ve gerçek firmware kabulü.','Başka STM32 ailesi veya kart revizyonu bu kapanmış profile otomatik dahil değildir.'],
];
for(const row of STM_SCOPE)if(row[1]==='Uygulama tamam')row[1]='Açık';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showSTMScope(board,showDialog){const b=STM32_BOARDS[board];showDialog('STM32 · Kapsam ve kontrol kaydı',`<p><strong>${esc(b.name)}</strong> · ${b.hz/1e6} MHz · ${b.flashSize/1024} KiB Flash / ${b.ram/1024} KiB SRAM</p><p><strong>STM32 fiziksel-silikon denetimi yeniden açıldı</strong></p><p>0.63 kapanış iddiası geri çekildi. Tablodaki açıklar geliştirme borcudur; yalnız kartta gerçekten bulunmayan bloklar ve laboratuvarda ölçülebilen analog etkiler ayrı gösterilir.</p><h3>Seçili kartta erişilebilir donanım</h3><table style="width:100%;font-size:12px"><thead><tr><th>Çevrebirim</th><th>Kartta erişim</th><th>Wirevo modeli</th></tr></thead><tbody>${stm32Capabilities(board).map(([name,present,model])=>`<tr><td>${esc(name)}</td><td>${present?'Var':'Yok'}</td><td>${esc(model)}</td></tr>`).join('')}</tbody></table><div style="overflow:auto"><table style="border-collapse:collapse;width:100%;table-layout:fixed;overflow-wrap:anywhere;font-size:12px"><thead><tr><th style="width:18%">Konu</th><th style="width:12%">Durum</th><th style="width:35%">Doğrulanan model</th><th style="width:35%">Kalan açık</th></tr></thead><tbody>${STM_SCOPE.map(([name,status,done,remaining])=>`<tr style="border-bottom:1px solid #334155"><td style="padding:10px;vertical-align:top"><strong>${esc(name)}</strong></td><td style="padding:10px;vertical-align:top;color:#7dd3fc">${status}</td><td style="padding:10px;vertical-align:top">${esc(done)}</td><td style="padding:10px;vertical-align:top">${esc(remaining)}</td></tr>`).join('')}</tbody></table></div><p>Kontrol: gerçek ARM C/C++ firmware, elektriksel hatlar, register/IRQ ve otomatik regresyon. “Tamamlandı” ancak modellenebilir denetim maddeleri sıfırlandığında yazılacaktır.</p><p><a href="./notices/STM32-SUPPORT-PROFILE.md" target="_blank">Destek profili ↗</a> · <a href="./notices/STM32-AUDIT.md" target="_blank">Ayrıntılı denetim ↗</a> · <a href="${esc(b.source)}" target="_blank">ST datasheet ↗</a>${b.boardSource?` · <a href="${esc(b.boardSource)}" target="_blank">Üretici şeması ↗</a>`:''}</p>`);document.getElementById('dialog').classList.add('stm-config-dialog');}
